/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This Scala translation demonstrates:
 * - Proper use of case classes and sealed traits for algebraic data types
 * - Type classes and implicit evidence for extensibility
 * - Variance annotations (covariant, contravariant, invariant)
 * - Pattern matching for type-safe dispatch
 * - Functional programming with Option, Either, and partial functions
 * - Generic type constraints with context bounds and view bounds
 * - Lazy evaluation and iterators for processing massive data
 * - Scala collections and their functional methods
 */

import scala.math.Numeric
import scala.reflect.ClassTag
import scala.collection.immutable
import scala.util.{Try, Success, Failure}
import java.time.{LocalDate, LocalDateTime, ZonedDateTime}
import java.math.BigDecimal
import scala.io.Source

// ============================================================================
// Type Aliases and Imports
// ============================================================================

object Tokenizer {

  // Type aliases for function types to improve readability
  type Normalizer = String => String
  type Validator[T] = T => Boolean
  type Handler[T] = T => Option[Token]

  // ============================================================================
  // Token Type and Token Classes
  // ============================================================================

  /**
   * Sealed trait representing different categories of tokens.
   * Using sealed trait instead of Enum provides better pattern matching
   * and is more idiomatic Scala.
   */
  sealed trait TokenType {
    def value: String
  }

  object TokenType {
    case object String extends TokenType {
      val value: String = "string"
    }
    case object Numeric extends TokenType {
      val value: String = "numeric"
    }
    case object Temporal extends TokenType {
      val value: String = "temporal"
    }
    case object Structured extends TokenType {
      val value: String = "structured"
    }
    case object Binary extends TokenType {
      val value: String = "binary"
    }
    case object Null extends TokenType {
      val value: String = "null"
    }

    /**
     * Parse a string to TokenType.
     * Returns Option to handle invalid inputs gracefully.
     */
    def fromString(s: String): Option[TokenType] = s.toLowerCase match {
      case "string"     => Some(String)
      case "numeric"    => Some(Numeric)
      case "temporal"   => Some(Temporal)
      case "structured" => Some(Structured)
      case "binary"     => Some(Binary)
      case "null"       => Some(Null)
      case _            => None
    }
  }

  /**
   * Immutable token representation.
   * Using case class provides automatic equals, hashCode, toString, and copy methods.
   * Metadata is immutable Map to prevent accidental mutations.
   */
  final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
  ) {
    /**
     * Create a new Token with additional metadata.
     * Preserves immutability by creating a new instance.
     */
    def withMetadata(entries: (String, Any)*): Token =
      this.copy(metadata = metadata ++ entries)

    /**
     * Get metadata by key, returning Option for safe access.
     */
    def getMetadata[A](key: String): Option[A] =
      metadata.get(key).map(_.asInstanceOf[A])

    /**
     * Check if token contains specific metadata key.
     */
    def hasMetadata(key: String): Boolean = metadata.contains(key)

    /**
     * Remove metadata by key.
     */
    def removeMetadata(key: String): Token =
      this.copy(metadata = metadata - key)
  }

  object Token {
    /**
     * Factory method for creating Token with TokenType.Null
     */
    def nullToken: Token = Token("NULL", TokenType.Null)

    /**
     * Factory method for creating Token with metadata as varargs
     */
    def apply(value: String, tokenType: TokenType, metadata: (String, Any)*): Token =
      new Token(value, tokenType, metadata.toMap)
  }

  /**
   * Mutable batch of tokens.
   * Used for accumulating tokens when building collections.
   * Uses internal state tracking to prevent post-processing mutations.
   */
  final class MutableTokenBatch(private var tokens: scala.collection.mutable.Buffer[Token] = scala.collection.mutable.Buffer.empty) {
    private var _processed: Boolean = false

    /**
     * Add a token to the batch.
     * Throws exception if batch has already been processed.
     */
    def add(token: Token): this.type = {
      if (_processed) {
        throw new IllegalStateException("Batch already processed")
      }
      tokens += token
      this
    }

    /**
     * Add multiple tokens at once.
     */
    def addAll(newTokens: Iterable[Token]): this.type = {
      if (_processed) {
        throw new IllegalStateException("Batch already processed")
      }
      tokens ++= newTokens
      this
    }

    /**
     * Mark the batch as processed, preventing further modifications.
     */
    def markProcessed(): Unit = {
      _processed = true
    }

    /**
     * Get all tokens as an immutable sequence.
     */
    def getTokens: immutable.Seq[Token] = tokens.toVector

    /**
     * Get the number of tokens in the batch.
     */
    def size: Int = tokens.size

    /**
     * Check if the batch has been processed.
     */
    def isProcessed: Boolean = _processed

    /**
     * Reset the batch for reuse.
     */
    def reset(): this.type = {
      tokens.clear()
      _processed = false
      this
    }

    /**
     * Convert batch to immutable list and clear.
     */
    def drain(): List[Token] = {
      val result = tokens.toList
      tokens.clear()
      this
    }
  }

  // ============================================================================
  // Generic Container Classes with Proper Variance
  // ============================================================================

  /**
   * Covariant container - can return subtypes.
   * Type parameter T is covariant (used only in output positions).
   * This allows a Container[Dog] to be used where Container[Animal] is expected.
   */
  final class TokenContainer[+T](private val items: Vector[T]) {
    def getAll: Vector[T] = items

    def isEmpty: Boolean = items.isEmpty

    def size: Int = items.size

    /**
     * Map tokens using a function that produces strings.
     * Uses functional programming to transform the container.
     */
    def mapToStrings(func: T => String): Vector[String] =
      items.map(func)

    /**
     * Map using a partial function for type-safe operations.
     */
    def collect[U](pf: PartialFunction[T, U]): TokenContainer[U] =
      new TokenContainer[U](items.collect(pf))

    /**
     * Filter tokens using a predicate.
     */
    def filter(predicate: T => Boolean): TokenContainer[T] =
      new TokenContainer[T](items.filter(predicate))

    /**
     * Fold operation for accumulating results.
     */
    def fold[U](init: U)(f: (U, T) => U): U =
      items.foldLeft(init)(f)
  }

  object TokenContainer {
    /**
     * Factory method for creating containers.
     */
    def apply[T](items: T*): TokenContainer[T] =
      new TokenContainer(items.toVector)

    /**
     * Create empty container.
     */
    def empty[T]: TokenContainer[T] =
      new TokenContainer(Vector.empty)
  }

  /**
   * Contravariant sink - can accept supertypes.
   * Type parameter T is contravariant (used only in input positions).
   * This allows a Sink[Animal] to be used where Sink[Dog] is expected.
   */
  final class TokenSink[-T] {
    private val received: scala.collection.mutable.Buffer[Any] =
      scala.collection.mutable.Buffer.empty

    /**
     * Receive an item into the sink.
     */
    def receive(item: T): Unit = {
      received += item
    }

    /**
     * Receive multiple items.
     */
    def receiveAll(items: Iterable[T]): Unit = {
      received ++= items
    }

    /**
     * Drain all received items and clear the buffer.
     */
    def drain(): List[Any] = {
      val result = received.toList
      received.clear()
      result
    }

    /**
     * Get size of received items.
     */
    def size: Int = received.size
  }

  object TokenSink {
    def apply[-T](): TokenSink[T] = new TokenSink[T]
  }

  /**
   * Invariant handler - exact type matching required.
   * Type parameter T is invariant (used in both input and output positions).
   * This maintains strict type safety without variance relaxation.
   */
  final class BivariantHandler[T](private var value: T) {
    def get: T = value

    def set(newValue: T): Unit = {
      value = newValue
    }

    /**
     * Transform the value using a function.
     */
    def transform(func: T => T): T = {
      value = func(value)
      value
    }

    /**
     * Modify the value using a partial function if applicable.
     */
    def modifyIfApplicable(pf: PartialFunction[T, T]): Unit = {
      if (pf.isDefinedAt(value)) {
        value = pf(value)
      }
    }
  }

  object BivariantHandler {
    def apply[T](default: T): BivariantHandler[T] = new BivariantHandler(default)
  }

  // ============================================================================
  // Type Classes for Extensible Tokenization
  // ============================================================================

  /**
   * Type class for converting values to tokens.
   * This allows users to define tokenization for custom types
   * without modifying the Tokenizer code.
   */
  trait Tokenizable[T] {
    def toToken(value: T): Token
  }

  object Tokenizable {
    /**
     * Implicit evidence for String tokenization.
     */
    implicit object StringTokenizable extends Tokenizable[String] {
      def toToken(value: String): Token =
        Token(value, TokenType.String)
    }

    /**
     * Implicit evidence for Int tokenization.
     */
    implicit object IntTokenizable extends Tokenizable[Int] {
      def toToken(value: Int): Token =
        Token(value.toString, TokenType.Numeric, Map("type" -> "int"))
    }

    /**
     * Implicit evidence for Long tokenization.
     */
    implicit object LongTokenizable extends Tokenizable[Long] {
      def toToken(value: Long): Token =
        Token(value.toString, TokenType.Numeric, Map("type" -> "long"))
    }

    /**
     * Implicit evidence for Double tokenization.
     */
    implicit object DoubleTokenizable extends Tokenizable[Double] {
      def toToken(value: Double): Token =
        Token(value.toString, TokenType.Numeric, Map("type" -> "double"))
    }

    /**
     * Implicit evidence for BigDecimal tokenization.
     */
    implicit object BigDecimalTokenizable extends Tokenizable[BigDecimal] {
      def toToken(value: BigDecimal): Token =
        Token(value.toString, TokenType.Numeric, Map("type" -> "bigdecimal"))
    }
  }

  // ============================================================================
  // Tokenizer Implementations
  // ============================================================================

  /**
   * Abstract base tokenizer with generic input type.
   * Uses abstract class to provide both abstract and concrete methods.
   */
  abstract class BaseTokenizer[T: ClassTag] {
    /**
     * Convert a single value to a token.
     */
    def tokenize(value: T): Token

    /**
     * Lazy tokenization of multiple values as an iterator.
     * Useful for streaming processing of large datasets.
     */
    def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
      values.iterator.map(tokenize)

    /**
     * Collect all tokens from tokenizing multiple values.
     */
    def tokenizeAll(values: Iterable[T]): Vector[Token] =
      tokenizeBatch(values).toVector

    /**
     * Process tokens through a function.
     */
    def map(values: Iterable[T])(f: Token => Token): Iterator[Token] =
      tokenizeBatch(values).map(f)
  }

  /**
   * Tokenizer for string and byte array types.
   * Handles encoding/decoding and optional normalization.
   */
  final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: Option[Normalizer] = None
  ) extends BaseTokenizer[String] {

    private val normalize: Normalizer =
      normalizer.getOrElse(identity)

    def tokenize(value: String): Token = {
      val normalized = normalize(value)
      Token(normalized, TokenType.String)
    }

    /**
     * Tokenize bytes with specified encoding.
     */
    def tokenizeBytes(value: Array[Byte]): Token = {
      val str = new String(value, encoding)
      tokenize(str)
    }

    /**
     * Create a new tokenizer with different normalizer.
     */
    def withNormalizer(f: Normalizer): StringTokenizer =
      new StringTokenizer(encoding, Some(f))
  }

  /**
   * Tokenizer for numeric types with precision handling.
   * Uses implicit Numeric evidence for handling different numeric types.
   */
  final class NumericTokenizer[T: Numeric](
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
  ) extends BaseTokenizer[T] {

    private val numeric = implicitly[Numeric[T]]

    def tokenize(value: T): Token = {
      val strValue = value match {
        case bd: BigDecimal =>
          String.format(s"%.${precision}f", bd)
        case d: Double =>
          String.format(s"%.${precision}f", d)
        case f: Float =>
          String.format(s"%.${precision}f", f)
        case _ => value.toString
      }

      Token(
        strValue,
        TokenType.Numeric,
        Map("originalType" -> value.getClass.getSimpleName) ++ formatOptions
      )
    }

    /**
     * Create a new tokenizer with different precision.
     */
    def withPrecision(newPrecision: Int): NumericTokenizer[T] =
      new NumericTokenizer[T](newPrecision, formatOptions)

    /**
     * Add format options.
     */
    def withFormatOptions(options: (String, Any)*): NumericTokenizer[T] =
      new NumericTokenizer[T](precision, formatOptions ++ options)
  }

  /**
   * Tokenizer for date/time types.
   * Supports multiple format options for different temporal types.
   */
  final class TemporalTokenizer(
    formatStr: Option[String] = None
  ) extends BaseTokenizer[java.time.temporal.Temporal] {

    private val ISO_FORMAT = "yyyy-MM-dd'T'HH:mm:ss"
    private val DATE_FORMAT = "yyyy-MM-dd"

    def tokenize(value: java.time.temporal.Temporal): Token = {
      val formatter = formatStr match {
        case Some(fmt) => java.time.format.DateTimeFormatter.ofPattern(fmt)
        case None => value match {
          case _: LocalDateTime =>
            java.time.format.DateTimeFormatter.ofPattern(ISO_FORMAT)
          case _: ZonedDateTime =>
            java.time.format.DateTimeFormatter.ofPattern(ISO_FORMAT)
          case _ =>
            java.time.format.DateTimeFormatter.ofPattern(DATE_FORMAT)
        }
      }

      Token(formatter.format(value), TokenType.Temporal)
    }

    /**
     * Tokenize LocalDate.
     */
    def tokenizeLocalDate(value: LocalDate): Token =
      tokenize(value)

    /**
     * Tokenize LocalDateTime.
     */
    def tokenizeLocalDateTime(value: LocalDateTime): Token =
      tokenize(value)

    /**
     * Create a new tokenizer with custom format.
     */
    def withFormat(fmt: String): TemporalTokenizer =
      new TemporalTokenizer(Some(fmt))
  }

  // ============================================================================
  // Universal Tokenizer with Pattern Matching
  // ============================================================================

  /**
   * Tokenizer that handles multiple types using pattern matching.
   * Uses sealed trait pattern and pattern matching for type-safe dispatch.
   * Much more idiomatic than Python's duck typing and overloads.
   */
  final class UniversalTokenizer {
    private val stringTokenizer = new StringTokenizer()
    private val numericTokenizer = new NumericTokenizer[Double]()
    private val temporalTokenizer = new TemporalTokenizer()

    /**
     * Main tokenization method using pattern matching.
     * Pattern matching is type-safe and exhaustive (when possible).
     */
    def tokenize(value: Any): Token = value match {
      case null => Token.nullToken
      case s: String => stringTokenizer.tokenize(s)
      case b: Array[Byte] => stringTokenizer.tokenizeBytes(b)
      case i: Int => numericTokenizer.tokenize(i.toDouble)
      case l: Long => numericTokenizer.tokenize(l.toDouble)
      case f: Float => numericTokenizer.tokenize(f.toDouble)
      case d: Double => numericTokenizer.tokenize(d)
      case bd: BigDecimal => numericTokenizer.tokenize(bd.doubleValue())
      case dt: LocalDateTime => temporalTokenizer.tokenizeLocalDateTime(dt)
      case d: LocalDate => temporalTokenizer.tokenizeLocalDate(d)
      case zdt: ZonedDateTime => temporalTokenizer.tokenize(zdt)
      case t: Tokenizable[_] =>
        Token(t.asInstanceOf[Tokenizable[Any]].toToken, TokenType.Structured)
      case other =>
        // Fallback to string conversion
        Token(other.toString, TokenType.String, Map("fallback" -> true))
    }

    /**
     * Tokenize with type evidence.
     * Requires implicit Tokenizable evidence for the type.
     */
    def tokenizeWithEvidence[T: Tokenizable](value: T): Token = {
      val tokenizable = implicitly[Tokenizable[T]]
      tokenizable.toToken(value)
    }

    /**
     * Batch tokenization.
     */
    def tokenizeBatch(values: Iterable[Any]): Iterator[Token] =
      values.iterator.map(tokenize)
  }

  // ============================================================================
  // Token Registry with Nested Generics
  // ============================================================================

  /**
   * Registry with complex nested generic types.
   * Uses immutable Map and Vector for thread-safe operations in distributed systems.
   */
  final class TokenRegistry[T] {
    private var registry: immutable.Map[String, TokenContainer[T]] =
      immutable.Map.empty
    private var handlers: Vector[Handler[T]] =
      Vector.empty

    /**
     * Register a container with a key.
     */
    def register(key: String, container: TokenContainer[T]): this.type = {
      registry = registry.updated(key, container)
      this
    }

    /**
     * Add a handler for processing items.
     */
    def addHandler(handler: Handler[T]): this.type = {
      handlers = handlers :+ handler
      this
    }

    /**
     * Process all items in a container through all handlers.
     * Returns a sequence of Option[Token], where None indicates
     * no handler matched the item.
     */
    def process(key: String): Vector[Option[Token]] = {
      registry.get(key) match {
        case None => Vector.empty
        case Some(container) =>
          container.getAll.map { item =>
            handlers.collectFirst {
              case handler if handler(item).nonEmpty => handler(item).get
            }
          }
      }
    }

    /**
     * Get registered keys.
     */
    def keys: Set[String] = registry.keySet

    /**
     * Get number of registered containers.
     */
    def size: Int = registry.size

    /**
     * Check if key is registered.
     */
    def contains(key: String): Boolean = registry.contains(key)
  }

  object TokenRegistry {
    def apply[T](): TokenRegistry[T] = new TokenRegistry[T]
  }

  // ============================================================================
  // Functor and Monad Patterns
  // ============================================================================

  /**
   * Functor for tokens with map operations.
   * Demonstrates functional programming patterns for processing tokens.
   */
  sealed trait TokenFunctor[+T] {
    def map[U](func: T => U): TokenFunctor[U]

    def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U]

    def getOrElse[U >: T](default: => U): U
  }

  final case class PureToken[T](value: T) extends TokenFunctor[T] {
    def map[U](func: T => U): TokenFunctor[U] =
      PureToken(func(value))

    def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] =
      func(value)

    def getOrElse[U >: T](default: => U): U = value
  }

  final case object EmptyToken extends TokenFunctor[Nothing] {
    def map[U](func: Nothing => U): TokenFunctor[U] = EmptyToken

    def flatMap[U](func: Nothing => TokenFunctor[U]): TokenFunctor[U] = EmptyToken

    def getOrElse[U >: Nothing](default: => U): U = default
  }

  object TokenFunctor {
    /**
     * Lift a value into the functor.
     */
    def pure[T](value: T): TokenFunctor[T] = PureToken(value)

    /**
     * Create an empty functor.
     */
    def empty[T]: TokenFunctor[T] = EmptyToken
  }

  /**
   * Monad operations on tokens.
   * Extends functor with applicative and monadic operations.
   */
  trait TokenMonad[T] extends TokenFunctor[T] {
    def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U]
  }

  final case class PureTokenMonad[T](value: T) extends TokenMonad[T] {
    def map[U](func: T => U): TokenFunctor[U] =
      PureTokenMonad(func(value))

    def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] =
      func(value)

    def getOrElse[U >: T](default: => U): U = value

    def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
      funcWrapped match {
        case PureTokenMonad(f) => PureTokenMonad(f(value))
        case _ => PureTokenMonad(value.asInstanceOf[U])
      }
  }

  // ============================================================================
  // JSON Tokenization with Recursive Types
  // ============================================================================

  /**
   * Sealed trait for JSON values with recursive definition.
   * This is the Scala way to handle recursive types safely.
   */
  sealed trait JsonValue
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: BigDecimal) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(values: Map[String, JsonValue]) extends JsonValue

  /**
   * Tokenizer for JSON structures with recursive types.
   */
  final class JsonTokenizer(pretty: Boolean = false) {
    /**
     * Tokenize a JSON value.
     */
    def tokenize(value: JsonValue): Token = {
      val jsonStr = if (pretty) {
        jsonToString(value, indent = 0)
      } else {
        jsonToStringCompact(value)
      }

      Token(jsonStr, TokenType.Structured, Map("json" -> true))
    }

    /**
     * Tokenize a value at a JSON path.
     * Path uses dot notation: "path.to.value"
     */
    def tokenizePath(value: JsonValue, path: String): Option[Token] = {
      val parts = path.split("\\.").toList
      navigateJson(value, parts).map(tokenize)
    }

    /**
     * Navigate JSON structure using path parts.
     */
    private def navigateJson(value: JsonValue, parts: List[String]): Option[JsonValue] =
      parts match {
        case Nil => Some(value)
        case head :: tail =>
          value match {
            case JsonObject(map) =>
              map.get(head).flatMap(v => navigateJson(v, tail))
            case JsonArray(arr) =>
              head.toIntOption.flatMap { idx =>
                if (idx >= 0 && idx < arr.length) {
                  navigateJson(arr(idx), tail)
                } else {
                  None
                }
              }
            case _ => None
          }
      }

    /**
     * Convert JSON value to pretty-printed string.
     */
    private def jsonToString(value: JsonValue, indent: Int): String = {
      val spaces = " " * indent
      val nextIndent = indent + 2
      val nextSpaces = " " * nextIndent

      value match {
        case JsonString(s) => s""""$s""""
        case JsonNumber(n) => n.toString
        case JsonBoolean(b) => b.toString
        case JsonNull => "null"
        case JsonArray(arr) =>
          if (arr.isEmpty) "[]"
          else {
            val items = arr
              .map(v => s"$nextSpaces${jsonToString(v, nextIndent)}")
              .mkString(",\n")
            s"[\n$items\n$spaces]"
          }
        case JsonObject(map) =>
          if (map.isEmpty) "{}"
          else {
            val items = map
              .map { case (k, v) =>
                s"""$nextSpaces"$k": ${jsonToString(v, nextIndent)}"""
              }
              .mkString(",\n")
            s"{\n$items\n$spaces}"
          }
      }
    }

    /**
     * Convert JSON value to compact string (no whitespace).
     */
    private def jsonToStringCompact(value: JsonValue): String = value match {
      case JsonString(s) => s""""$s""""
      case JsonNumber(n) => n.toString
      case JsonBoolean(b) => b.toString
      case JsonNull => "null"
      case JsonArray(arr) =>
        arr.map(jsonToStringCompact).mkString("[", ",", "]")
      case JsonObject(map) =>
        map
          .map { case (k, v) => s""""$k":${jsonToStringCompact(v)}""" }
          .mkString("{", ",", "}")
    }
  }

  // ============================================================================
  // Whitespace Tokenizer
  // ============================================================================

  /**
   * Basic tokenizer that splits text by whitespace.
   * Demonstrates a practical, real-world tokenization use case for NLP and text processing.
   */
  final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ) {
    private val punctuation: Set[Char] =
      ".,!?;:'\"()[]{}<>@#$%^&*-=+\\|`~".toSet

    /**
     * Process a single word into a token string.
     * Returns Option to handle filtered words gracefully.
     */
    private def processToken(word: String): Option[String] = {
      var processed = word

      if (stripPunctuation) {
        processed = processed
          .dropWhile(punctuation.contains)
          .reverse
          .dropWhile(punctuation.contains)
          .reverse
      }

      if (lowercase) {
        processed = processed.toLowerCase
      }

      if (processed.length < minLength) {
        None
      } else if (maxLength.exists(processed.length > _)) {
        Some(processed.take(maxLength.get))
      } else if (processed.nonEmpty) {
        Some(processed)
      } else {
        None
      }
    }

    /**
     * Split text by whitespace and return list of tokens.
     */
    def tokenize(text: String): Vector[Token] = {
      val words = text.split("\\s+").iterator

      val tokens = scala.collection.mutable.Buffer.empty[Token]
      var position = 0

      for (word <- words) {
        processToken(word).foreach { processed =>
          tokens += Token(
            processed,
            TokenType.String,
            Map("position" -> position, "original" -> word)
          )
          position += 1
        }
      }

      tokens.toVector
    }

    /**
     * Split text by whitespace and return list of token strings.
     * Convenience method that extracts just the string values.
     */
    def tokenizeToStrings(text: String): Vector[String] =
      tokenize(text).map(_.value)

    /**
     * Tokenize text and return tokens with character positions.
     * Returns tuples of (token_string, start_pos, end_pos).
     */
    def tokenizeWithPositions(text: String): Vector[(String, Int, Int)] = {
      val words = text.split("\\s+")
      val result = scala.collection.mutable.Buffer.empty[(String, Int, Int)]
      var currentPos = 0

      for (word <- words) {
        val start = text.indexOf(word, currentPos)
        val end = start + word.length

        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }

        currentPos = end
      }

      result.toVector
    }

    /**
     * Return the number of tokens in the text.
     */
    def countTokens(text: String): Int = tokenize(text).size

    /**
     * Create a new tokenizer with lowercase option.
     */
    def withLowercase(enabled: Boolean): WhitespaceTokenizer =
      new WhitespaceTokenizer(enabled, minLength, maxLength, stripPunctuation)

    /**
     * Create a new tokenizer with length constraints.
     */
    def withLengthConstraints(min: Int, max: Option[Int]): WhitespaceTokenizer =
      new WhitespaceTokenizer(lowercase, min, max, stripPunctuation)

    /**
     * Create a new tokenizer with punctuation stripping.
     */
    def withPunctuationStripping(enabled: Boolean): WhitespaceTokenizer =
      new WhitespaceTokenizer(lowercase, minLength, maxLength, enabled)
  }

  object WhitespaceTokenizer {
    def apply(
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None,
      stripPunctuation: Boolean = false
    ): WhitespaceTokenizer =
      new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
  }

  // ============================================================================
  // Builder Pattern with Fluent Interface
  // ============================================================================

  /**
   * Fluent builder for creating custom tokenizers.
   * Demonstrates the builder pattern in Scala with method chaining.
   * Uses scala.collection.immutable collections for thread-safety.
   */
  final class TokenizerBuilder[T: ClassTag] {
    private var normalizers: Vector[Normalizer] = Vector.empty
    private var validators: Vector[Validator[T]] = Vector.empty
    private var metadata: Map[String, Any] = Map.empty

    /**
     * Add a normalizer function to the builder.
     * Normalizers are applied in order to string representations.
     */
    def withNormalizer(normalizer: Normalizer): this.type = {
      normalizers = normalizers :+ normalizer
      this
    }

    /**
     * Add a validator function to the builder.
     * Validators throw an exception if they return false.
     */
    def withValidator(validator: Validator[T]): this.type = {
      validators = validators :+ validator
      this
    }

    /**
     * Add metadata entries using varargs.
     */
    def withMetadata(entries: (String, Any)*): this.type = {
      metadata = metadata ++ entries
      this
    }

    /**
     * Build the final tokenizer function.
     * Returns a function that can be used for tokenization.
     */
    def build(): T => Token = { value: T =>
      // Validate
      validators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      // Convert to string
      var strValue: String = value.toString

      // Normalize
      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      // Return token with metadata
      Token(strValue, TokenType.String, metadata)
    }

    /**
     * Build and immediately apply to a value.
     */
    def buildAndApply(value: T): Token = build()(value)

    /**
     * Build and tokenize a batch of values.
     */
    def buildAndBatch(values: Iterable[T]): Vector[Token] =
      values.map(build()).toVector
  }

  object TokenizerBuilder {
    /**
     * Create a new builder for type T.
     */
    def apply[T: ClassTag](): TokenizerBuilder[T] =
      new TokenizerBuilder[T]()
  }

  // ============================================================================
  // Convenience Functions
  // ============================================================================

  /**
   * Global tokenize function using UniversalTokenizer.
   * Provides simple access to tokenization for any type.
   */
  lazy val universalTokenizer = new UniversalTokenizer()

  def tokenize(value: Any): Token =
    universalTokenizer.tokenize(value)

  /**
   * Batch tokenize multiple values.
   */
  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] =
    universalTokenizer.tokenizeBatch(values)

  /**
   * Convert value to token using type class evidence.
   */
  def toToken[T: Tokenizable](value: T): Token = {
    val tokenizable = implicitly[Tokenizable[T]]
    tokenizable.toToken(value)
  }

  /**
   * Create a token with metadata.
   * Convenience function for creating tokens with additional context.
   */
  def withMetadata(
    value: String,
    tokenType: TokenType,
    entries: (String, Any)*
  ): Token =
    Token(value, tokenType, entries.toMap)

}

